class Solution {
    public List<List<String>> displayTable(List<List<String>> orders){
        Set<String> foods=new TreeSet<>();
        Map<Integer,Map<String,Integer>> tables=new TreeMap<>();
        for(List<String> order:orders){
            int table=Integer.parseInt(order.get(1));
            String food=order.get(2);
            foods.add(food);
            tables.computeIfAbsent(table,key->new HashMap<>()).merge(food,1,Integer::sum);
        }
        List<List<String>> answer=new ArrayList<>();
        List<String> header=new ArrayList<>();
        header.add("Table");
        header.addAll(foods);
        answer.add(header);
        for(Map.Entry<Integer,Map<String,Integer>> entry:tables.entrySet()){
            List<String> row=new ArrayList<>();
            row.add(String.valueOf(entry.getKey()));
            for(String food:foods)row.add(String.valueOf(entry.getValue().getOrDefault(food,0)));
            answer.add(row);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun displayTable(orders:List<List<String>>):List<List<String>>{
        val foods=java.util.TreeSet<String>();
        val tables=java.util.TreeMap<Int,MutableMap<String,Int>>();
        for(order in orders){
            val table=order[1].toInt();
            val food=order[2];
            foods.add(food);
            val count=tables.getOrPut(table){
                mutableMapOf()
            };
            count[food]=(count[food]?:0)+1
        };
        val answer=mutableListOf<List<String>>();
        answer.add(listOf("Table")+foods);
        for((table,count)in tables)answer.add(listOf(table.toString())+foods.map{
            (count[it]?:0).toString()
        });
        return answer
    }
}

